void bubble_sort(int* a, size_t n) {
    for (size_t i = 0; i + 1 < n; ++i) {
        bool swapped = false;
        for (size_t j = 0; j + 1 < n - i; ++j) {
            if (a[j] > a[j + 1]) {
                int tmp = a[j];
                a[j] = a[j + 1];
                a[j + 1] = tmp;
                swapped = true;
            }
        }
        if (!swapped) break;
    }
}

static void merge_sort_impl(int* a, int* buf, size_t left, size_t right) {
    if (right - left <= 1) return;
    size_t mid = left + (right - left) / 2;
    merge_sort_impl(a, buf, left, mid);
    merge_sort_impl(a, buf, mid, right);
    // Merge
    size_t i = left, j = mid, k = left;
    while (i < mid && j < right) {
        if (a[i] <= a[j]) buf[k++] = a[i++];
        else buf[k++] = a[j++];
    }
    while (i < mid) buf[k++] = a[i++];
    while (j < right) buf[k++] = a[j++];
    for (size_t p = left; p < right; ++p) a[p] = buf[p];
}

void merge_sort(int* a, size_t n) {
    if (n <= 1) return;
    int* buf = (int*)malloc(n * sizeof(int));
    if (!buf) return;
    merge_sort_impl(a, buf, 0, n);
